-- Full organization identities see six contexts, while Audit Direncanakan excludes the undated QA; assigned identities never see the unrelated row.
SELECT pg_temp.actor('d0000000-0000-0000-0000-000000000001');CREATE TEMP TABLE admin_payload AS SELECT public.get_internal_audit_dashboard(2096,NULL,NULL)p;
SELECT pg_temp.ok((SELECT pg_temp.metric(p,'planned')=5 FROM admin_payload),'Admin full scope and undated QA excluded from Audit Direncanakan');
SELECT pg_temp.ok((SELECT p->'fiscal_years' @> '[2095]'::jsonb FROM admin_payload),'full scope includes Annual Plan FY without Instructions');
SELECT pg_temp.ok((SELECT pg_temp.metric(p,'attention')=2 FROM admin_payload),'Audit Perlu Perhatian counts two unique QA contexts while overlapping conditions on one QA count once');
SELECT pg_temp.ok((SELECT (p->'plan_actual'->0->>'label')='April 2096' AND (p->'plan_actual'->11->>'label')='Maret 2097' FROM admin_payload),'April-March order');
SELECT pg_temp.ok((SELECT (p->'plan_actual'->0->>'plan')::int=0 AND (p->'plan_actual'->1->>'plan')::int=1 FROM admin_payload),'only current plan revision counted');
SELECT pg_temp.ok((SELECT pg_temp.metric(p,'established')=4 FROM admin_payload),'ZERO FINDING, Product, Manufacturing and PUBLISHED established; pending blocked');
SELECT pg_temp.ok((SELECT (p->'finding_health'->>'open')::int=2 AND (p->'finding_health'->>'closed')::int=1 AND (p->'finding_health'->>'pending_review')::int=1 FROM admin_payload),'Finding states');
SELECT pg_temp.ok((SELECT (p->'finding_health'->'categories'->>'A')::int=1 AND (p->'finding_health'->'categories'->>'B')::int=2 AND (p->'finding_health'->'categories'->>'C')::int=1 FROM admin_payload),'A/B/C categories');
SELECT pg_temp.ok((SELECT (p->'ltp_health'->>'temporary_overdue')::int=1 AND (p->'ltp_health'->>'permanent_overdue')::int=1 FROM admin_payload),'open Temporary/Permanent overdue and Closed excluded');
SELECT pg_temp.ok((SELECT (p->'ltp_health'->>'verification_pending')::int=2 FROM admin_payload),'verification pending includes Auditor Review/Returned and excludes Admin Review/Closed');
SELECT pg_temp.ok((SELECT (SELECT sum((x->>'value')::int) FROM jsonb_array_elements(p->'execution_status')x)=8 FROM admin_payload),'execution statuses are mutually exclusive and exhaustive');
SELECT pg_temp.ok((SELECT (SELECT (x->>'value')::int FROM jsonb_array_elements(p->'execution_status')x WHERE x->>'label'='Belum Mulai')=1 AND (SELECT (x->>'value')::int FROM jsonb_array_elements(p->'execution_status')x WHERE x->>'label'='Berjalan')=1 AND (SELECT (x->>'value')::int FROM jsonb_array_elements(p->'execution_status')x WHERE x->>'label'='Execution Selesai')=1 AND (SELECT (x->>'value')::int FROM jsonb_array_elements(p->'execution_status')x WHERE x->>'label'='Menunggu Finalisasi Finding')=1 AND (SELECT (x->>'value')::int FROM jsonb_array_elements(p->'execution_status')x WHERE x->>'label'='Established')=4 FROM admin_payload),'execution status precedence produces one row in each non-Established state and four Established');
SELECT pg_temp.actor('d0000000-0000-0000-0000-000000000002');SELECT pg_temp.ok(pg_temp.metric(public.get_internal_audit_dashboard(2096,NULL,NULL),'planned')=5,'Company Lead full scope');
SELECT pg_temp.actor('d0000000-0000-0000-0000-000000000003');SELECT pg_temp.ok(pg_temp.metric(public.get_internal_audit_dashboard(2096,NULL,NULL),'planned')=4,'Auditor assigned planned rows only');SELECT pg_temp.ok(NOT(public.get_internal_audit_dashboard(2096,NULL,NULL)->'fiscal_years' @> '[2095]'::jsonb),'restricted Auditor does not receive plan-only organization FY');SELECT pg_temp.ok(pg_temp.metric(public.get_internal_audit_dashboard(2096,NULL,'d0300000-0000-0000-0000-000000000002'),'planned')=0,'Auditor unrelated Process hidden');
SELECT pg_temp.ok(pg_temp.metric(public.get_internal_audit_dashboard(2096,'ChecklistProduk',NULL),'planned')=1,'Audit Type filter');SELECT pg_temp.ok(NOT(public.get_internal_audit_dashboard(2096,'ChecklistProduk',NULL)->>'plan_actual_available')::boolean AND public.get_internal_audit_dashboard(2096,'ChecklistProduk',NULL)->>'plan_actual_message'='Plan vs Aktual FORM-001 tidak memiliki dimensi Jenis Audit.','Audit Type never fabricates FORM-001 Plan/Actual');SELECT pg_temp.ok((public.get_internal_audit_dashboard(2096,NULL,NULL)->'my_actions'->0->>'count')::int=2,'Auditor Tugas Saya excludes unrelated rows');SELECT pg_temp.ok((public.get_internal_audit_dashboard(2096,NULL,NULL)->'my_actions'->1->>'count')::int=2,'Auditor verification task includes Auditor Review and Auditor Returned only');SELECT pg_temp.ok(pg_temp.metric(public.get_internal_audit_dashboard(2096,NULL,'d0300000-0000-0000-0000-000000000001'),'planned')=4,'Process filter');
SELECT pg_temp.actor('d0000000-0000-0000-0000-000000000004');SELECT pg_temp.ok(pg_temp.metric(public.get_internal_audit_dashboard(2096,NULL,NULL),'planned')=1,'unrelated Auditor isolated');
SELECT pg_temp.actor('d0000000-0000-0000-0000-000000000005');SELECT pg_temp.ok(pg_temp.metric(public.get_internal_audit_dashboard(2096,NULL,NULL),'planned')=1,'Auditee A sees shared QA context');SELECT pg_temp.ok((public.get_internal_audit_dashboard(2096,NULL,NULL)->'finding_health'->>'pending_review')::int=1 AND (public.get_internal_audit_dashboard(2096,NULL,NULL)->'finding_health'->'categories'->>'B')::int=0,'Auditee A sees Finding A but not shared-row Finding B');SELECT pg_temp.ok((public.get_internal_audit_dashboard(2096,NULL,NULL)->'ltp_health'->>'open')::int=1,'Auditee A sees CAR A only');SELECT pg_temp.ok(NOT EXISTS(SELECT 1 FROM jsonb_array_elements(public.get_internal_audit_dashboard(2096,NULL,NULL)->'recent_activity')x WHERE x->>'label'='QA-DB02' AND x->>'detail'='TEAM_SUBMITTED'),'Auditee A activity excludes Finding B');
SELECT pg_temp.actor('d0000000-0000-0000-0000-000000000006');SELECT pg_temp.ok((public.get_internal_audit_dashboard(2096,NULL,NULL)->'finding_health'->'categories'->>'A')::int=0,'Auditee B excludes Finding A on shared QA');SELECT pg_temp.ok((public.get_internal_audit_dashboard(2096,NULL,NULL)->'finding_health'->'categories'->>'B')::int=2,'Auditee B sees only its shared Finding plus its separate Finding');SELECT pg_temp.ok(NOT EXISTS(SELECT 1 FROM jsonb_array_elements(public.get_internal_audit_dashboard(2096,NULL,NULL)->'recent_activity')x WHERE x->>'label'='QA-DB02' AND x->>'detail'='PLOR_EDITED'),'Auditee B activity excludes Finding A');
SELECT pg_temp.actor('d0000000-0000-0000-0000-000000000007');SELECT pg_temp.ok((public.get_internal_audit_dashboard(2096,NULL,NULL)->'finding_health'->'categories'->>'A')::int=1 AND (public.get_internal_audit_dashboard(2096,NULL,NULL)->'finding_health'->'categories'->>'B')::int=0,'Manager A sees only Finding A on shared QA');
SELECT pg_temp.actor('d0000000-0000-0000-0000-000000000008');SELECT pg_temp.ok((public.get_internal_audit_dashboard(2096,NULL,NULL)->'finding_health'->'categories'->>'A')::int=0 AND (public.get_internal_audit_dashboard(2096,NULL,NULL)->'finding_health'->'categories'->>'B')::int=2,'Manager B sees its shared and separate Findings, not Finding A');
SELECT pg_temp.ok(pg_temp.metric(public.get_internal_audit_dashboard(2080,NULL,NULL),'planned')=0,'no-data FY valid zero payload');
SELECT pg_temp.actor('d0000000-0000-0000-0000-000000000003');SELECT pg_temp.ok(NOT(public.get_internal_audit_dashboard(2094,NULL,NULL)->>'plan_actual_available')::boolean AND public.get_internal_audit_dashboard(2094,NULL,NULL)->>'plan_actual_message'='Belum ada Rencana Audit Tahunan untuk FY ini.','authorized Instruction FY without Annual Plan returns explicit unavailable state');
RESET ROLE;
SELECT pg_temp.ok(has_function_privilege('authenticated','public.get_internal_audit_dashboard(integer,text,uuid)','EXECUTE'),'authenticated may execute Dashboard RPC');
SELECT pg_temp.ok(NOT has_function_privilege('authenticated','public.dashboard_can_access_instruction_row(uuid)','EXECUTE'),'private scope helper is not client executable');
